import React, { useState, useEffect } from 'react';
import { HashRouter as Router, Routes, Route, Navigate, useLocation, Link } from 'react-router-dom';
import Navigation from './components/Navigation';
import Sidebar from './components/Sidebar';
import Login from './pages/Login';
import Signup from './pages/Signup';
import UserDashboard from './pages/UserDashboard';
import VideoWatch from './pages/VideoWatch';
import Profile from './pages/Profile';
import UserQuizzes from './pages/UserQuizzes';
import Certificates from './pages/Certificates';
import Plans from './pages/Plans';
import StudyRooms from './pages/StudyRooms';
import LiveClasses from './pages/LiveClasses';
import LiveClassroom from './pages/LiveClassroom';
import FAQ from './pages/FAQ';
import PrivacyPolicy from './pages/PrivacyPolicy';
import TermsConditions from './pages/TermsConditions';
import logoImg from './assets/logo.png';
import { getCurrentUser, api } from './services/api';
import { LanguageProvider } from './context/LanguageContext';
import { ThemeCustomizerProvider } from './context/ThemeCustomizerContext';
import { ThemeCustomizerDrawer, ScreenIdChip } from './components/AppearanceCustomizer';

// Route protection for authenticated users
const ProtectedRoute = ({ children }) => {
  const user = getCurrentUser();
  if (!user) {
    return <Navigate to="/login" replace />;
  }
  return children;
};

// Route protection based on user roles
const RoleRoute = ({ children, allowedRoles }) => {
  const user = getCurrentUser();
  if (!user) {
    return <Navigate to="/login" replace />;
  }
  if (!allowedRoles.includes(user.role)) {
    return <Navigate to="/" replace />;
  }
  return children;
};

// Sub-component to manage navigation rendering based on route
const AppLayout = ({ theme, setTheme }) => {
  const location = useLocation();
  const user = getCurrentUser();
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  
  // Hide global navigation on Login / Signup / Reset Password screens
  const isAuthPage = ['/login', '/signup', '/forgot-password', '/reset-password'].includes(location.pathname);
  const isLegalOrPublicPage = ['/faq', '/privacy', '/terms'].includes(location.pathname);

  // 10 minutes inactivity auto-logout listener with Cross-Tab Sync
  useEffect(() => {
    if (!user || isAuthPage) return;

    const INACTIVITY_TIMEOUT_MS = 10 * 60 * 1000; // 10 minutes in milliseconds
    let timeoutId = null;

    const checkAndPerformAutoLogout = () => {
      const lastActivity = parseInt(localStorage.getItem('lastUserActivity') || '0', 10);
      const timeSinceLastActivity = Date.now() - lastActivity;

      if (timeSinceLastActivity >= INACTIVITY_TIMEOUT_MS) {
        sessionStorage.setItem('inactivityLoggedOut', 'true');
        api.auth.logout(2);
        window.location.hash = '/login';
      } else {
        const remainingTime = INACTIVITY_TIMEOUT_MS - timeSinceLastActivity;
        timeoutId = setTimeout(checkAndPerformAutoLogout, remainingTime);
      }
    };

    const resetTimer = () => {
      const now = Date.now();
      localStorage.setItem('lastUserActivity', now.toString());

      if (timeoutId) clearTimeout(timeoutId);
      timeoutId = setTimeout(checkAndPerformAutoLogout, INACTIVITY_TIMEOUT_MS);
    };

    const handleStorageChange = (e) => {
      if (e.key === 'lastUserActivity') {
        if (timeoutId) clearTimeout(timeoutId);
        const lastActivity = parseInt(e.newValue || '0', 10);
        const remainingTime = INACTIVITY_TIMEOUT_MS - (Date.now() - lastActivity);
        if (remainingTime > 0) {
          timeoutId = setTimeout(checkAndPerformAutoLogout, remainingTime);
        } else {
          checkAndPerformAutoLogout();
        }
      }
    };

    const activityEvents = ['mousemove', 'mousedown', 'keydown', 'scroll', 'touchstart', 'click'];
    
    let lastEventTime = Date.now();
    const handleUserActivity = () => {
      const now = Date.now();
      if (now - lastEventTime > 1000) {
        lastEventTime = now;
        resetTimer();
      }
    };

    window.addEventListener('storage', handleStorageChange);
    activityEvents.forEach(event => window.addEventListener(event, handleUserActivity));
    resetTimer();

    return () => {
      if (timeoutId) clearTimeout(timeoutId);
      window.removeEventListener('storage', handleStorageChange);
      activityEvents.forEach(event => window.removeEventListener(event, handleUserActivity));
    };
  }, [user, isAuthPage]);

  const toggleSidebar = () => {
    setIsSidebarOpen(prev => !prev);
  };

  useEffect(() => {
    setIsSidebarOpen(false);
  }, [location.pathname]);

  const showSidebar = !isAuthPage && user && user.role === 'user';
  const isFullWidthPage = isAuthPage || isLegalOrPublicPage || (user && user.role === 'user');

  return (
    <div style={{ height: '100vh', display: 'flex', flexDirection: 'column', background: 'var(--bg-primary)', width: '100%', maxWidth: '100vw', overflow: 'hidden' }}>
      {!isAuthPage && user && (
        <Navigation 
          toggleSidebar={toggleSidebar} 
          theme={theme} 
          setTheme={setTheme} 
        />
      )}
      {!user && isLegalOrPublicPage && (
        <header style={{
          height: '60px',
          background: 'var(--bg-secondary)',
          borderBottom: '1px solid var(--border-color)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          padding: '0 24px',
          boxSizing: 'border-box',
          zIndex: 100
        }}>
          <Link to="/" style={{ display: 'flex', alignItems: 'center', gap: '10px', textDecoration: 'none' }}>
            <img src={logoImg} alt="XLURN" style={{ height: '32px' }} />
            <span style={{ fontSize: '18px', fontWeight: 800, color: 'var(--text-primary)', letterSpacing: '-0.5px' }}>XLURN</span>
          </Link>
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
            <Link to="/login" style={{
              padding: '8px 18px',
              borderRadius: '8px',
              background: 'var(--accent-primary, #2563eb)',
              color: '#ffffff',
              textDecoration: 'none',
              fontSize: '13px',
              fontWeight: 600
            }}>
              Sign In
            </Link>
          </div>
        </header>
      )}
      <div style={{ flex: 1, display: 'flex', position: 'relative', height: (user || isLegalOrPublicPage) && !isAuthPage ? 'calc(100vh - 60px)' : '100vh', overflow: 'hidden' }}>
        {showSidebar && (
          <Sidebar 
            isOpen={isSidebarOpen} 
            onClose={() => setIsSidebarOpen(false)} 
          />
        )}
        <div style={{ 
          flex: 1, 
          padding: isFullWidthPage ? '0' : '40px',
          position: 'relative',
          minWidth: 0,
          height: '100%',
          overflowY: 'auto'
        }}>
          <Routes>
          {/* Public Authentication routes */}
          <Route path="/login" element={user ? <Navigate to="/" replace /> : <Login />} />
          <Route path="/forgot-password" element={user ? <Navigate to="/" replace /> : <Login initialAuthMode="forgot" />} />
          <Route path="/reset-password" element={user ? <Navigate to="/" replace /> : <Login initialAuthMode="reset" />} />
          <Route path="/signup" element={user ? <Navigate to="/" replace /> : <Signup />} />

          {/* Public Legal & Info routes */}
          <Route path="/faq" element={<FAQ />} />
          <Route path="/privacy" element={<PrivacyPolicy />} />
          <Route path="/terms" element={<TermsConditions />} />

          {/* Protected routes */}
          <Route path="/profile" element={
            <ProtectedRoute>
              <Profile />
            </ProtectedRoute>
          } />

          <Route path="/plans" element={
            <ProtectedRoute>
              <Plans />
            </ProtectedRoute>
          } />

          {/* User Specific Paths */}
          <Route path="/quizzes" element={
            <RoleRoute allowedRoles={['user']}>
              <UserQuizzes />
            </RoleRoute>
          } />

          <Route path="/certificates" element={
            <RoleRoute allowedRoles={['user']}>
              <Certificates />
            </RoleRoute>
          } />

          <Route path="/study-rooms" element={
            <RoleRoute allowedRoles={['user']}>
              <StudyRooms />
            </RoleRoute>
          } />

          <Route path="/live-classes" element={
            <RoleRoute allowedRoles={['user']}>
              <LiveClasses />
            </RoleRoute>
          } />

          <Route path="/live/:id" element={
            <RoleRoute allowedRoles={['user']}>
              <LiveClassroom />
            </RoleRoute>
          } />

          <Route path="/watch/:id" element={
            <RoleRoute allowedRoles={['user']}>
              <VideoWatch />
            </RoleRoute>
          } />

          <Route path="/" element={
            <ProtectedRoute>
              <DashboardRedirect />
            </ProtectedRoute>
          } />

          {/* Fallback route */}
          <Route path="*" element={<Navigate to="/" replace />} />
        </Routes>
      </div>
    </div>
  </div>
  );
};

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null };
  }
  static getDerivedStateFromError(error) {
    return { hasError: true, error };
  }
  componentDidCatch(error, errorInfo) {
    console.error("ErrorBoundary caught an error", error, errorInfo);
  }
  render() {
    if (this.state.hasError) {
      return (
        <div style={{ padding: '40px', background: '#fee2e2', color: '#991b1b', borderRadius: '8px', margin: '20px', overflow: 'auto', maxHeight: '90vh' }}>
          <h2 style={{ marginBottom: '16px' }}>Something went wrong (Rendering Error)</h2>
          <pre style={{ whiteSpace: 'pre-wrap', fontSize: '14px', fontFamily: 'monospace' }}>
            {this.state.error?.stack || String(this.state.error)}
          </pre>
        </div>
      );
    }
    return this.props.children;
  }
}

// Helper component to redirect authenticated user to their role-specific dashboard
const DashboardRedirect = () => {
  const user = getCurrentUser();
  if (!user) return <Navigate to="/login" replace />;
  if (user.role !== 'user') return <Navigate to="/login" replace />;
  return (
    <ErrorBoundary>
      <UserDashboard />
    </ErrorBoundary>
  );
};

function App() {
  const [theme, setTheme] = useState(() => localStorage.getItem('theme') || 'dark');

  useEffect(() => {
    localStorage.setItem('theme', theme);
    if (theme === 'light') {
      document.body.classList.add('light-theme');
    } else {
      document.body.classList.remove('light-theme');
    }
  }, [theme]);

  return (
    <ErrorBoundary>
      <LanguageProvider>
        <ThemeCustomizerProvider externalTheme={theme} setExternalTheme={setTheme}>
          <Router>
            <AppLayout theme={theme} setTheme={setTheme} />
            <ThemeCustomizerDrawer />
            <ScreenIdChip />
          </Router>
        </ThemeCustomizerProvider>
      </LanguageProvider>
    </ErrorBoundary>
  );
}

export default App;
